<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\Customer\Action\Command;

use Module\Customer\Action\Command\ValidateAccessTokenCmd;
use Module\Customer\Support\CustomerBag;
use Module\Customer\Support\Security\TokenService;
use Module\Shared\Exception\AppNeverException;
use Module\Shared\Exception\AppUnauthorizedException;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Tests\UnitTestCase;

class ValidateAccessTokenCmdTest extends UnitTestCase
{
    private ValidateAccessTokenCmd $sut;

    private CustomerBag $customerBag;

    public function setUp(): void
    {
        parent::setUp();

        $tokenService = $this->createStub(TokenService::class);
        $tokenService->method('decodeAccessToken')->willReturnCallback(function (string $token): array {
            return match ($token) {
                'valid-token' => ['uid' => 5, 'stid' => 10],
                'no-stid-token' => ['uid' => 5],
                'no-uid-token' => [],
                default => throw new AppUnauthorizedException('JWT token is invalid.'),
            };
        });

        $this->customerBag = new CustomerBag();

        $this->sut = new ValidateAccessTokenCmd(
            $tokenService,
            $this->customerBag
        );
    }

    #[Test, DataProvider('dataProviderGetUserBadgeFrom')]
    public function getUserBadgeFrom(
        string $accessToken,
        string $expectedIdentifier,
        string $expectedExceptionClass,
        string $expectedExceptionMessage,
        ?int $expectedCustomerId,
        int $expectedStoreId,
    ): void {
        if ($expectedExceptionClass) {
            $this->expectException($expectedExceptionClass);
            $this->expectExceptionMessageMatches('/^' . preg_quote($expectedExceptionMessage, '/') . '$/');
        }

        $result = $this->sut->getUserBadgeFrom($accessToken);

        $this->assertSame($expectedIdentifier, $result->getUserIdentifier());
        $this->assertSame($expectedCustomerId, $this->customerBag->customerId);
        $this->assertSame($expectedStoreId, $this->customerBag->selectedStoreId);
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderGetUserBadgeFrom(): array
    {
        return [
            'success' => [
                'accessToken' => 'valid-token',
                'expectedIdentifier' => '5',
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expectedCustomerId' => 5,
                'expectedStoreId' => 10,
            ],
            'success without stid' => [
                'accessToken' => 'no-stid-token',
                'expectedIdentifier' => '5',
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expectedCustomerId' => 5,
                'expectedStoreId' => 0,
            ],
            'invalid token' => [
                'accessToken' => 'bad-token',
                'expectedIdentifier' => '',
                'expectedExceptionClass' => AppUnauthorizedException::class,
                'expectedExceptionMessage' => 'JWT token is invalid.',
                'expectedCustomerId' => null,
                'expectedStoreId' => 0,
            ],
            'missing uid' => [
                'accessToken' => 'no-uid-token',
                'expectedIdentifier' => '',
                'expectedExceptionClass' => AppNeverException::class,
                'expectedExceptionMessage' => 'Missing "uid" in JWT token',
                'expectedCustomerId' => null,
                'expectedStoreId' => 0,
            ],
        ];
    }
}
